package scanner

import (
	"context"
	"io/fs"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"time"

	"github.com/navidrome/navidrome/consts"
	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/utils"
)

type (
	dirStats struct {
		Path            string
		ModTime         time.Time
		Images          []string
		ImagesUpdatedAt time.Time
		HasPlaylist     bool
		AudioFilesCount uint32
	}
)

func walkDirTree(ctx context.Context, rootFolder string) (<-chan dirStats, chan error) {
	results := make(chan dirStats)
	errC := make(chan error)
	go func() {
		defer close(results)
		defer close(errC)
		rootPath, err := filepath.Abs(rootFolder)
		logPath := rootFolder
		if err == nil {
			logPath = rootPath
			err = walkFolder(ctx, rootPath, results)
		}
		if err != nil {
			log.Error(ctx, "There were errors reading directories from filesystem", "path", logPath, err)
			errC <- err
		}
		log.Debug(ctx, "Finished reading directories from filesystem", "path", logPath)
	}()
	return results, errC
}

func walkFolder(ctx context.Context, dirPath string, results chan<- dirStats) error {
	select {
	case <-ctx.Done():
		return nil
	default:
	}

	children, stats, err := loadDir(ctx, dirPath)
	if err != nil {
		return err
	}
	for _, child := range children {
		if err := walkFolder(ctx, child, results); err != nil {
			return err
		}
	}

	dirPath = filepath.Clean(dirPath)
	log.Trace(ctx, "Found directory", "dir", dirPath, "audioCount", stats.AudioFilesCount,
		"images", stats.Images, "hasPlaylist", stats.HasPlaylist)
	stats.Path = dirPath
	results <- *stats

	return nil
}

func loadDir(ctx context.Context, dirPath string) ([]string, *dirStats, error) {
	var children []string
	stats := &dirStats{}

	dirInfo, err := os.Stat(dirPath)
	if err != nil {
		log.Error(ctx, "Error stating dir", "path", dirPath, err)
		return nil, nil, err
	}
	stats.ModTime = dirInfo.ModTime()

	dir, err := os.Open(dirPath)
	if err != nil {
		log.Error(ctx, "Error in Opening directory", "path", dirPath, err)
		return children, stats, err
	}
	defer dir.Close()
	if !dirInfo.IsDir() {
		log.Error(ctx, "Not a directory", "path", dirPath)
		return children, stats, nil
	}

	for _, entry := range fullReadDir(ctx, dir) {
		isDir, err := isDirOrSymlinkToDir(dirPath, entry)
		// Skip invalid symlinks
		if err != nil {
			log.Error(ctx, "Invalid symlink", "dir", filepath.Join(dirPath, entry.Name()), err)
			continue
		}
		entryPath := filepath.Join(dirPath, entry.Name())
		if isDir && !isDirIgnored(dirPath, entry) {
			readable, err := utils.IsDirReadable(entryPath)
			if err != nil {
				log.Warn(ctx, "Skipping unreadable directory", "path", entryPath, err)
			}
			if readable {
				children = append(children, entryPath)
				continue
			}
		}

		fileInfo, err := entry.Info()
		if err != nil {
			log.Error(ctx, "Error getting fileInfo", "name", entry.Name(), err)
			return children, stats, err
		}
		if fileInfo.ModTime().After(stats.ModTime) {
			stats.ModTime = fileInfo.ModTime()
		}
		switch {
		case model.IsAudioFile(entry.Name()):
			stats.AudioFilesCount++
		case model.IsValidPlaylist(entry.Name()):
			stats.HasPlaylist = true
		case model.IsImageFile(entry.Name()):
			stats.Images = append(stats.Images, entry.Name())
			if fileInfo.ModTime().After(stats.ImagesUpdatedAt) {
				stats.ImagesUpdatedAt = fileInfo.ModTime()
			}
		}
	}
	return children, stats, nil
}

// fullReadDir reads all files in the folder, skipping the ones with errors.
// It also detects when it is "stuck" with an error in the same directory over and over.
// In this case, it stops and returns whatever it was able to read until it got stuck.
// See discussion here: https://github.com/navidrome/navidrome/issues/1164#issuecomment-881922850
func fullReadDir(ctx context.Context, dir fs.ReadDirFile) []fs.DirEntry {
	var allEntries []fs.DirEntry
	var prevErrStr = ""
	for {
		entries, err := dir.ReadDir(-1)
		allEntries = append(allEntries, entries...)
		if err == nil {
			break
		}
		log.Warn(ctx, "Skipping DirEntry", err)
		if prevErrStr == err.Error() {
			log.Error(ctx, "Duplicate DirEntry failure, bailing", err)
			break
		}
		prevErrStr = err.Error()
	}
	sort.Slice(allEntries, func(i, j int) bool { return allEntries[i].Name() < allEntries[j].Name() })
	return allEntries
}

// isDirOrSymlinkToDir returns true if and only if the dirEnt represents a file
// system directory, or a symbolic link to a directory. Note that if the dirEnt
// is not a directory but is a symbolic link, this method will resolve by
// sending a request to the operating system to follow the symbolic link.
// originally copied from github.com/karrick/godirwalk, modified to use dirEntry for
// efficiency for go 1.16 and beyond
func isDirOrSymlinkToDir(baseDir string, dirEnt os.DirEntry) (bool, error) {
	if dirEnt.IsDir() {
		return true, nil
	}
	if dirEnt.Type()&os.ModeSymlink == 0 {
		return false, nil
	}
	// Does this symlink point to a directory?
	fileInfo, err := os.Stat(filepath.Join(baseDir, dirEnt.Name()))
	if err != nil {
		return false, err
	}
	return fileInfo.IsDir(), nil
}

// isDirIgnored returns true if the directory represented by dirEnt contains an
// `ignore` file (named after skipScanFile)
func isDirIgnored(baseDir string, dirEnt os.DirEntry) bool {
	// allows Album folders for albums which eg start with ellipses
	if strings.HasPrefix(dirEnt.Name(), ".") && !strings.HasPrefix(dirEnt.Name(), "..") {
		return true
	}
	if runtime.GOOS == "windows" && strings.EqualFold(dirEnt.Name(), "$Recycle.Bin") {
		return true
	}
	_, err := os.Stat(filepath.Join(baseDir, dirEnt.Name(), consts.SkipScanFile))
	return err == nil
}
package utils

import (
	"os"

	"github.com/navidrome/navidrome/log"
)

// IsDirReadable reports whether the directory at path can be opened.
func IsDirReadable(path string) (bool, error) {
	dir, err := os.Open(path)
	if err != nil {
		return false, err
	}
	if err := dir.Close(); err != nil {
		log.Warn("Error closing directory", "path", path, err)
	}
	return true, nil
}
// - collect all albumIDs and artistIDs from previous steps
// - refresh the collected albums and artists with the metadata from the mediafiles
// For each changed folder, process playlists:
// - If the playlist is not in the DB, import it, setting sync = true
// - If the playlist is in the DB and sync == true, import it, or else skip it
// Delete all empty albums, delete all empty artists, clean-up playlists
func (s *TagScanner) Scan(ctx context.Context, lastModifiedSince time.Time, progress chan uint32) (int64, error) {
	ctx = auth.WithAdminUser(ctx, s.ds)
	start := time.Now()

	// Special case: if lastModifiedSince is zero, re-import all files
	fullScan := lastModifiedSince.IsZero()

	// If the media folder is empty (no music and no subfolders), abort to avoid deleting all data from DB
	empty, err := isDirEmpty(ctx, s.rootFolder)
	if err != nil {
		return 0, err
	}
	if empty && !fullScan {
		log.Error(ctx, "Media Folder is empty. Aborting scan.", "folder", s.rootFolder)
		return 0, nil
	}

	allDBDirs, err := s.getDBDirTree(ctx)
	if err != nil {
		return 0, err
	}

	allFSDirs := dirMap{}
	var changedDirs []string
	s.cnt = &counters{}
	genres := newCachedGenreRepository(ctx, s.ds.Genre(ctx))
	s.mapper = newMediaFileMapper(s.rootFolder, genres)
	refresher := newRefresher(s.ds, s.cacheWarmer, allFSDirs)

	log.Trace(ctx, "Loading directory tree from music folder", "folder", s.rootFolder)
	foldersFound, walkerError := walkDirTree(ctx, s.rootFolder)

	for {
		folderStats, more := <-foldersFound
		if !more {
			break
		}
		progress <- folderStats.AudioFilesCount
		allFSDirs[folderStats.Path] = folderStats

		if s.folderHasChanged(folderStats, allDBDirs, lastModifiedSince) {
			changedDirs = append(changedDirs, folderStats.Path)
			log.Debug("Processing changed folder", "dir", folderStats.Path)
			err := s.processChangedDir(ctx, refresher, fullScan, folderStats.Path)
			if err != nil {
				log.Error("Error updating folder in the DB", "dir", folderStats.Path, err)
			}
		}
	}

		log.Debug("Playlist auto-import is disabled")
	}

	err = s.ds.GC(log.NewContext(ctx), s.rootFolder)
	log.Info("Finished processing Music Folder", "folder", s.rootFolder, "elapsed", time.Since(start),
		"added", s.cnt.added, "updated", s.cnt.updated, "deleted", s.cnt.deleted, "playlistsImported", s.cnt.playlists)

	return s.cnt.total(), err
}

func isDirEmpty(ctx context.Context, dirPath string) (bool, error) {
	children, stats, err := loadDir(ctx, dirPath)
	if err != nil {
		return false, err
	}
	return len(children) == 0 && stats.AudioFilesCount == 0, nil
}

func (s *TagScanner) getDBDirTree(ctx context.Context) (map[string]struct{}, error) {
	start := time.Now()
	log.Trace(ctx, "Loading directory tree from database", "folder", s.rootFolder)

	repo := s.ds.MediaFile(ctx)
	dirs, err := repo.FindPathsRecursively(s.rootFolder)
	if err != nil {
		return nil, err

	var mfs model.MediaFiles
	for _, md := range mds {
		mf := s.mapper.toMediaFile(md)
		mfs = append(mfs, mf)
	}
	return mfs, nil
}

func loadAllAudioFiles(dirPath string) (map[string]os.DirEntry, error) {
	files, err := os.ReadDir(dirPath)
	if err != nil {
		return nil, err
	}
	fileInfos := make(map[string]os.DirEntry)
	for _, f := range files {
		if f.IsDir() {
			continue
		}
		if strings.HasPrefix(f.Name(), ".") {
			continue
		}
		filePath := filepath.Join(dirPath, f.Name())
		if !model.IsAudioFile(filePath) {
			continue
		}
		fileInfos[filePath] = f
	}

	return fileInfos, nil
}

